Here's a modern MSTest test class covering async success, failure, timeout, and cancellation:

```csharp
[TestClass]
public class DataFetcherTests
{
    // MSTest natively supports async Task test methods — just return Task.
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        var handler = new MockHttpMessageHandler(
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("hello")
            });
        var fetcher = new DataFetcher(new HttpClient(handler));

        var result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("hello", result);
    }

    [TestMethod]
    public async Task FetchAsync_Throws_OnNonSuccessStatusCode()
    {
        var handler = new MockHttpMessageHandler(
            new HttpResponseMessage(HttpStatusCode.InternalServerError));
        var fetcher = new DataFetcher(new HttpClient(handler));

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    // [Timeout] is in milliseconds and works on async tests.
    // The test fails automatically if it exceeds the limit.
    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_CompletesWithinTimeout()
    {
        var handler = new MockHttpMessageHandler(
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("fast")
            });
        var fetcher = new DataFetcher(new HttpClient(handler));

        var result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("fast", result);
    }

    // Verify the method honors the CancellationToken.
    [TestMethod]
    public async Task FetchAsync_Throws_WhenCancelled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // pre-cancel

        var handler = new MockHttpMessageHandler(
            new HttpResponseMessage(HttpStatusCode.OK));
        var fetcher = new DataFetcher(new HttpClient(handler));

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Verify cancellation mid-flight via a slow handler.
    [TestMethod]
    public async Task FetchAsync_Throws_WhenCancelledDuringRequest()
    {
        using var cts = new CancellationTokenSource();
        var handler = new MockHttpMessageHandler(async ct =>
        {
            await Task.Delay(TimeSpan.FromSeconds(10), ct); // simulate slow
            return new HttpResponseMessage(HttpStatusCode.OK);
        });
        var fetcher = new DataFetcher(new HttpClient(handler));

        cts.CancelAfter(TimeSpan.FromMilliseconds(50));

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Minimal mock handler to avoid real HTTP calls.
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        private readonly Func<CancellationToken, Task<HttpResponseMessage>> _factory;

        public MockHttpMessageHandler(HttpResponseMessage response)
            : this(_ => Task.FromResult(response)) { }

        public MockHttpMessageHandler(Func<CancellationToken, Task<HttpResponseMessage>> factory)
            => _factory = factory;

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
            => _factory(cancellationToken);
    }
}
```

**Key patterns:**

| Pattern | How |
|---|---|
| **Async tests** | Return `async Task` — MSTest awaits them natively |
| **Timeouts** | `[Timeout(ms)]` — works with async; fails the test on expiry |
| **Cancellation** | Create a `CancellationTokenSource`, cancel it, assert `TaskCanceledException` |
| **No real HTTP** | Subclass `HttpMessageHandler` to control responses without a network |

Avoid `async void` test methods — MSTest can't observe their exceptions, so failures are silently lost.
